import { useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { RoutePath } from '../routes/types/RoutePath';
import { browser_api } from '@app/browser_api';
import { getLocalStorageData } from '@app/storage/local/shared';

import { LocalStorageKey } from '@app/storage/local/types/sharedTypes';

export function useChangeDevice(): void {
  const navigate = useNavigate();

  useEffect(() => {
    async function handleDeviceChangeError(): Promise<void> {
      const { deviceConflictUserId } = await getLocalStorageData(
        LocalStorageKey.DeviceConflictUserId,
      );
      if (deviceConflictUserId) {
        navigate(RoutePath.ChangeDevice, {
          state: { userId: deviceConflictUserId },
        });
      }
    }

    void handleDeviceChangeError();
  }, [navigate]);

  useEffect(() => {
    async function listener(changes: {
      [LocalStorageKey.DeviceConflictUserId]?: { newValue?: boolean };
    }): Promise<void> {
      const newValue =
        changes?.[LocalStorageKey.DeviceConflictUserId]?.newValue;
      if (newValue) {
        navigate(RoutePath.ChangeDevice, {
          state: {
            userId: newValue,
          },
        });
      }
    }

    browser_api.storage.onChanged.addListener(listener);
    return () => {
      browser_api.storage.onChanged.removeListener(listener);
    };
  }, [navigate]);
}
