import { createMemoryRouter } from 'react-router-dom';
import { ModeSwitcherContextProvider } from '../contexts/ModeSwitcher/ModeSwitcherContext';
import { AllInternetPromo } from './AllInternetPromo';
import { CancelPremium } from './CancelPremium';
import { ChangeDevice } from './ChangeDevice';
import { FreeInfoPersuasion } from './FreeInfoPersuasion';
import { PremiumInfo } from './PremiumInfo';
import { PremiumInfoPersuasion } from './PremiumInfoPersuasion';
import { Root } from './Root';
import { UnavailableTrial } from './UnavailableTrial';
import { PremiumSalePersuasion } from './types/PremiumSalePersuasion';
import { RoutePath } from './types/RoutePath';
import { GiftAdvertising } from './GiftAdvertising';
import { Settings } from '@popup/project/youboost/routes/Settings';
import { SubscriptionManagement } from '@popup/project/youboost/routes/SubscriptionManagement';
import { Payment } from '@popup/project/youboost/routes/Payment';
import { Tariffs } from './Tariffs/ui/Tariffs';
import { TransitionWrapper } from '@popup/project/youboost/components/shared/TransitionWrapper';
import { Support } from '@popup/project/youboost/routes/Support';
import { RefuseGift } from '@popup/project/youboost/routes/RefuseGift';
import { ChangeServer } from '@popup/project/youboost/routes/ChangeServer';
import { ServerChanged } from '@popup/project/youboost/routes/ServerChanged';
import { TelegramAuthPromo } from '@popup/project/youboost/routes/TelegramAuthPromo';
import { getAndClearInitialEntry } from '@popup/shared/utils/getAndClearInitialEntry';
import { NavigationLayout } from '@popup/shared/components/NavigationLayout/NavigationLayout';
import { PromoCodeActivated } from './PromoCodeActivated';
import { GlobalError } from '@popup/project/youboost/components/GlobalError';
import { ErrorLayout } from '@popup/project/youboost/components/ErrorLayout';
import {
  errorLayoutLoader,
  supportPageLoader,
} from '@popup/project/youboost/loaders';

const initialEntry = await getAndClearInitialEntry(RoutePath.Root);

export const router = createMemoryRouter(
  [
    {
      element: <NavigationLayout />,
      errorElement: <GlobalError />,
      children: [
        {
          path: RoutePath.Support,
          loader: supportPageLoader,
          element: (
            <TransitionWrapper>
              <Support />
            </TransitionWrapper>
          ),
        },
        {
          loader: errorLayoutLoader,
          element: <ErrorLayout />,
          children: [
            {
              path: RoutePath.Root,
              element: (
                <TransitionWrapper>
                  <ModeSwitcherContextProvider>
                    <Root />
                  </ModeSwitcherContextProvider>
                </TransitionWrapper>
              ),
            },
            {
              path: RoutePath.PremiumInfo,
              element: (
                <TransitionWrapper>
                  <PremiumInfo />
                </TransitionWrapper>
              ),
            },
            {
              path: RoutePath.CancelPremium,
              element: (
                <TransitionWrapper>
                  <CancelPremium />
                </TransitionWrapper>
              ),
            },
            {
              path: RoutePath.ChangeDevice,
              element: (
                <TransitionWrapper>
                  <ChangeDevice />
                </TransitionWrapper>
              ),
            },
            {
              path: RoutePath.Payment,
              element: (
                <TransitionWrapper>
                  <Payment />
                </TransitionWrapper>
              ),
            },
            {
              path: RoutePath.AllInternetPromo,
              element: (
                <TransitionWrapper>
                  <AllInternetPromo />
                </TransitionWrapper>
              ),
            },
            {
              path: RoutePath.FreeInfoPersuasion,
              element: (
                <TransitionWrapper>
                  <FreeInfoPersuasion />
                </TransitionWrapper>
              ),
            },
            {
              path: RoutePath.PremiumInfoPersuasion,
              element: (
                <TransitionWrapper>
                  <PremiumInfoPersuasion />
                </TransitionWrapper>
              ),
            },
            {
              path: RoutePath.PremiumSalePersuasion,
              element: (
                <TransitionWrapper>
                  <PremiumSalePersuasion />
                </TransitionWrapper>
              ),
            },
            {
              path: RoutePath.UnavailableTrial,
              element: (
                <TransitionWrapper>
                  <UnavailableTrial />
                </TransitionWrapper>
              ),
            },
            {
              path: RoutePath.GiftAdvertising,
              element: (
                <TransitionWrapper>
                  <GiftAdvertising />
                </TransitionWrapper>
              ),
            },
            {
              path: RoutePath.Settings,
              element: (
                <TransitionWrapper>
                  <Settings />
                </TransitionWrapper>
              ),
            },
            {
              path: RoutePath.SubscriptionManagement,
              element: (
                <TransitionWrapper>
                  <SubscriptionManagement />
                </TransitionWrapper>
              ),
            },
            {
              path: RoutePath.Tariffs,
              element: (
                <TransitionWrapper>
                  <Tariffs />
                </TransitionWrapper>
              ),
            },
            {
              path: RoutePath.RefuseGift,
              element: (
                <TransitionWrapper>
                  <RefuseGift />
                </TransitionWrapper>
              ),
            },
            {
              path: RoutePath.ChangeServer,
              element: (
                <TransitionWrapper>
                  <ChangeServer />
                </TransitionWrapper>
              ),
            },
            {
              path: RoutePath.ServerChanged,
              element: (
                <TransitionWrapper>
                  <ServerChanged />
                </TransitionWrapper>
              ),
            },
            {
              path: RoutePath.TelegramAuthPromo,
              element: (
                <TransitionWrapper>
                  <TelegramAuthPromo />
                </TransitionWrapper>
              ),
            },
            {
              path: RoutePath.PromoCodeActivated,
              element: (
                <TransitionWrapper>
                  <PromoCodeActivated />
                </TransitionWrapper>
              ),
            },
          ],
        },
      ],
    },
  ],
  {
    initialEntries: [initialEntry],
  },
);
