import { useState } from 'react';
import { Alarms } from '@app/alarms/shared';
import { browser_api } from '@app/browser_api';
import { LocalStorageKey } from '@app/storage/local/types/sharedTypes';
import { setLocalStorageData } from '@app/storage/local/shared';

const OTHER_EXTENSIONS_CONFLICT_WARNING_PERIOD_IN_MINUTES = process.env
  .OTHER_EXTENSIONS_CONFLICT_WARNING_PERIOD_IN_MINUTES
  ? parseInt(process.env.OTHER_EXTENSIONS_CONFLICT_WARNING_PERIOD_IN_MINUTES)
  : 1440;

type Result = {
  showProxyConflict: boolean;
  handleProxyConflictClick: () => Promise<void>;
};

export function useProxyConflict(
  defaultShowProxyConflict: Result['showProxyConflict'],
): Result {
  const [showProxyConflict, setShowProxyConflict] = useState<
    Result['showProxyConflict']
  >(defaultShowProxyConflict);

  const handleProxyConflictClick: Result['handleProxyConflictClick'] =
    async () => {
      await setLocalStorageData({ [LocalStorageKey.PopupWasOpened]: true });
      setShowProxyConflict(false);
      browser_api.alarms.create(Alarms.ExtensionConflictWarningProxy, {
        periodInMinutes: OTHER_EXTENSIONS_CONFLICT_WARNING_PERIOD_IN_MINUTES,
      });
    };

  return {
    showProxyConflict,
    handleProxyConflictClick,
  };
}
