import { FC, useCallback, useEffect, useState } from 'react';
import {
  SupportAlternative,
  SupportTg,
} from '@popup/project/youboost/components/SupportContent';
import { RoutePath } from '@popup/project/youboost/routes/types/RoutePath';
import {
  LocalStorageData,
  LocalStorageKey,
} from '@app/storage/local/types/sharedTypes';
import {
  deleteLocalStorageData,
  setLocalStorageData,
} from '@app/storage/local/shared';
import { useLoaderData, useNavigate } from 'react-router-dom';

interface Props {}
interface LoaderDataType {
  supportUrl: string;
  isSupportViaTg: boolean;
  hasPremium: NonNullable<LocalStorageData['hasPremium']>;
  userId: LocalStorageData['userId'];
}

const clearInitialEntry = async () => {
  await deleteLocalStorageData([LocalStorageKey.PopupInitialEntry]);
};

export const Support: FC<Props> = ({}) => {
  const navigate = useNavigate();

  const data = useLoaderData() as LoaderDataType;
  const [{ supportUrl, isSupportViaTg, hasPremium, userId }] = useState(data);

  useEffect(() => {
    void setLocalStorageData({
      [LocalStorageKey.PopupInitialEntry]: RoutePath.Support,
    });
  }, []);

  const closeHandler = useCallback(async () => {
    await clearInitialEntry();
    navigate(RoutePath.Root);
  }, [navigate]);

  return isSupportViaTg ? (
    <SupportTg closeHandler={closeHandler} supportUrl={supportUrl} />
  ) : (
    <SupportAlternative
      clearInitialEntry={clearInitialEntry}
      closeHandler={closeHandler}
      supportUrl={supportUrl}
      hasPremium={hasPremium}
      userId={userId}
    />
  );
};
