import { type ComponentProps, FC, type ReactNode } from 'react';
import styles from './SecondaryWrapper.module.css';
import {
  ChevronDown,
  Close,
} from '@popup/project/youboost/components/shared/icons';
import clsx from 'clsx';

export interface Props {
  header: ReactNode;
  children: ReactNode;
  footer?: ReactNode;
  backButtonProps?: Omit<ComponentProps<'button'>, 'onClick'> & {
    onClick: () => void | Promise<void>;
  };
  closeClickHandler?: () => void | Promise<void>;
}

export const SecondaryWrapper: FC<Props> = ({
  footer,
  children,
  header,
  backButtonProps,
  closeClickHandler,
}) => {
  return (
    <div className={styles.wrapper}>
      <div className={styles.header}>
        <div className={styles.icon}>
          {backButtonProps && (
            <button
              {...backButtonProps}
              className={clsx(
                styles.action,
                styles.icon,
                backButtonProps.className,
              )}
              data-testid={'back-button'}
              data-close="close-button"
            >
              <ChevronDown className={styles.backIcon} />
            </button>
          )}
        </div>
        <div className={styles.middle}>{header}</div>
        {closeClickHandler && (
          <button
            onClick={closeClickHandler}
            className={clsx(styles.action, styles.icon)}
            data-testid={'close-button'}
            data-close="close-button"
          >
            <Close className={styles.icon} />
          </button>
        )}
      </div>
      <div className={styles.main}>{children}</div>
      {footer && <div className={styles.footer}>{footer}</div>}
    </div>
  );
};
