import { getLocalStorageData } from '@app/storage/local/shared';
import { LocalStorageKey } from '@app/storage/local/types/sharedTypes';
import { getMetaApiData } from '@utils/metaApiData';
import { browser_api } from '@app/browser_api';
import { Alarms } from '@app/alarms/shared';

export async function errorLayoutLoader() {
  const [
    {
      errorMessage,
      isSubscriptionInfoError,
      isBrowserError,
      isProxyControlledByOtherExtensions,
      isAdBlockersWork,
    },
    { requiredVersion },
    extensionConflictWarningProxyAlarm,
    extensionConflictWarningAdBlockerAlarm,
  ] = await Promise.all([
    getLocalStorageData([
      LocalStorageKey.ErrorMessage,
      LocalStorageKey.IsSubscriptionInfoError,
      LocalStorageKey.IsBrowserError,
      LocalStorageKey.IsProxyControlledByOtherExtensions,
      LocalStorageKey.IsAdBlockersWork,
    ]),
    getMetaApiData(),
    browser_api.alarms.get(Alarms.ExtensionConflictWarningProxy),
    browser_api.alarms.get(Alarms.ExtensionConflictWarningAdBlocker),
  ]);

  return {
    errorMessage,
    isSubscriptionInfoError,
    isBrowserError,
    showProxyConflict:
      Boolean(isProxyControlledByOtherExtensions) &&
      !extensionConflictWarningProxyAlarm,
    showAdBlockerConflict:
      Boolean(isAdBlockersWork) && !extensionConflictWarningAdBlockerAlarm,
    requiredVersion,
  };
}
