import { useCallback } from 'react';
import {
  LocalStorageData,
  LocalStorageKey,
} from '@app/storage/local/types/sharedTypes';
import { useLocalStorage } from '@popup/shared/hooks/useLocalStorage';

export function useErrorScreen(
  defaultErrorMessage: LocalStorageData['errorMessage'],
) {
  const [errorMessage, setErrorMessage] = useLocalStorage(
    [LocalStorageKey.ErrorMessage],
    defaultErrorMessage,
  );

  const handleRetry = useCallback(async () => {
    await setErrorMessage(undefined);
  }, [setErrorMessage]);

  return {
    errorMessage,
    handleRetry,
  };
}
