import { type ReactNode, useCallback } from 'react';
import { useTranslation } from 'react-i18next';
import { browser_api } from '@app/browser_api';
import { Footer } from './Footer';
import { setLocalStorageData } from '@app/storage/local/shared';
import { LocalStorageKey } from '@app/storage/local/types/sharedTypes';
import s from './Error.module.css';
import { StatusLayout } from '@popup/project/youboost/components/shared/StatusLayout';
import { Warning } from '@popup/project/youboost/components/shared/icons';

type ErrorProps = {
  title?: string | null;
  icon?: ReactNode;
  subtitle?: string | null;
  text?: ReactNode;
  code?: number;
  footer?: ReactNode;
  children?: ReactNode;
  onClose?: () => void;
};

export function Error({
  title,
  icon,
  subtitle,
  text,
  code,
  footer,
  children,
  onClose,
}: ErrorProps): JSX.Element {
  const { t } = useTranslation('youboost', {
    keyPrefix: 'error.default',
  });

  const defaultTitle = t('title');
  const defaultSubtitle = t('subtitle');
  const defaultText = t('text');

  const handleClose = useCallback(() => {
    if (onClose) {
      onClose();
    } else {
      setLocalStorageData({ [LocalStorageKey.ShouldOpenPopup]: true }).finally(
        () => {
          browser_api.runtime.reload();
        },
      );
    }
  }, [onClose]);

  return (
    <StatusLayout
      headerTitle={title || defaultTitle}
      footer={footer ?? <Footer />}
      text={text ?? defaultText}
      closeClickHandler={handleClose}
      icon={icon || <Warning />}
      bodyTitle={subtitle || defaultSubtitle}
    >
      {children}
      {code && <p className={s.code}>{`${t('code')}: ${code}`}</p>}
    </StatusLayout>
  );
}
