import { FC } from 'react';
import s from './Footer.module.css';
import { Button } from '@popup/project/youboost/components/shared/Button';
import { RoutePath } from '@popup/project/youboost/routes/types/RoutePath';
import { useTranslation } from 'react-i18next';
import { useNavigate } from 'react-router-dom';
import { Actions } from '@app/actions/shared';
import { messageDispatcher } from '@app/infrastructure/messageDispatcher';
import { featureStore } from '@ulta-plus/extension-feature-toggle';
import { Feature } from '@app/features/types/Feature';
import { getMetaApiData } from '@utils/metaApiData';
import { buildSupportUrl } from '@utils/buildSupportUrl';
import { getLocalStorageData } from '@app/storage/local/shared';
import { LocalStorageKey } from '@app/storage/local/types/sharedTypes';
import { browser_api } from '@app/browser_api';
import { logger } from '@utils/logger';

interface Props {}

export const Footer: FC<Props> = ({}) => {
  const { t } = useTranslation('youboost', { keyPrefix: 'change-server' });
  const navigate = useNavigate();

  const changeHandler = async () => {
    try {
      const res = await messageDispatcher.send({
        action: Actions.ChangeServerManually,
      });
      navigate(RoutePath.ServerChanged);
    } catch (e) {
      navigate(RoutePath.Support);
    }
  };

  const supportHandler = async () => {
    try {
      const { featuresList } = await featureStore.getSnapshotAsync();
      const isSupportViaTg = featuresList[Feature.IsSupportViaTg];
      if (isSupportViaTg) {
        navigate(RoutePath.Support);
      } else {
        const [{ supportUrl }, { deviceId, userId, email, hasPremium }] =
          await Promise.all([
            getMetaApiData(),
            getLocalStorageData([
              LocalStorageKey.UserId,
              LocalStorageKey.DeviceId,
              LocalStorageKey.email,
              LocalStorageKey.HasPremium,
            ]),
          ]);
        if (!hasPremium) {
          navigate(RoutePath.Support);
          return;
        }
        if (!supportUrl) {
          throw new Error('Support URL is missing');
        }
        const url = buildSupportUrl({
          baseUrl: supportUrl,
          params: { ID: userId, deviceId, email },
        });
        await browser_api.tabs.create({ url });
      }
    } catch (e) {
      logger.error('Error in supportHandler:', e);
      navigate(RoutePath.Support);
    }
  };

  return (
    <div className={s.buttons}>
      <Button color="secondary" size="default" onClick={changeHandler}>
        {t('change-btn')}
      </Button>
      <Button color="tertiary" size="default" onClick={supportHandler}>
        {t('support-btn')}
      </Button>
    </div>
  );
};
