import { FC } from 'react';
import { Trans, useTranslation } from 'react-i18next';
import { SecondaryWrapper } from '@popup/project/youboost/components/shared/SecondaryWrapper';
import { Footer } from './Footer/Footer';
import s from './SupportTg.module.css';
import { IconTextSection } from '@popup/project/youboost/components/IconTextSection';
import { SmileMessage } from '@popup/project/youboost/components/shared/icons';
import { QRCodeSVG } from 'qrcode.react';

interface Props {
  closeHandler: () => Promise<void>;
  supportUrl: string;
}

export const SupportTg: FC<Props> = ({ closeHandler, supportUrl }) => {
  const { t } = useTranslation('youboost', { keyPrefix: 'support-page' });

  return (
    <SecondaryWrapper
      header={t('header')}
      footer={<Footer supportUrl={supportUrl} closeHandler={closeHandler} />}
      closeClickHandler={closeHandler}
    >
      <div className={s.body} data-testid={'settings-body'}>
        <IconTextSection
          icon={<SmileMessage className={s.icon} />}
          text={
            <span className={s.description}>
              <Trans t={t} i18nKey="description" components={{ br: <br /> }} />
            </span>
          }
        >
          <div className={s.qrBox}>
            <QRCodeSVG
              value={supportUrl}
              size={136}
              bgColor={'transparent'}
              fgColor={'var(--qr-code-color)'}
              title={supportUrl}
            />
            <div className={s.url}>{supportUrl.replace('https://', '')}</div>
          </div>
        </IconTextSection>
      </div>
    </SecondaryWrapper>
  );
};
