import { ReactNode } from 'react';
import styles from './IconTextSection.module.css';

export type Props = {
  icon: ReactNode;
  text: ReactNode;
  title?: string;
  children?: ReactNode;
};

export const IconTextSection = ({
  icon,
  title,
  text,
  children,
}: Props): JSX.Element => {
  return (
    <div className={styles['icon-text-section']}>
      <div className={styles.icon}>{icon}</div>
      {title && <h2 className={styles.title}>{title}</h2>}
      <p className={styles.text}>{text}</p>
      {children}
    </div>
  );
};
