import React, { FC } from 'react';
import { Outlet, useLoaderData } from 'react-router-dom';
import {
  useErrorScreen,
  useIsOutdatedVersion,
  useProxyConflict,
} from '@popup/project/youboost/hooks';
import { Error } from '@popup/project/youboost/components/shared/errors/Error';
import {
  type LocalStorageData,
  LocalStorageKey,
} from '@app/storage/local/types/sharedTypes';
import { type MetaApiData } from '@app/storage/local/types/expirableTypes';
import { versionStringToNumber } from '@popup/shared/helpers/versionStringToNumber';
import { browser_api } from '@app/browser_api';
import { OldVersionError } from '@popup/project/youboost/components/shared/errors/oldVersionError';
import { useLocalStorage } from '@popup/shared/hooks/useLocalStorage';
import { BrowserError } from '@popup/project/youboost/components/shared/errors/BrowserError';
import { ProxyControlledByOtherExtensions } from '@popup/project/youboost/components/ProxyControlledByOtherExtensions';
import { useFeaturesList } from '@app/features/hooks/useFeaturesList';
import { Feature } from '@app/features/types/Feature';
import { useAdBlockerConflict } from '@popup/project/youboost/hooks/useAdBlockerConflict/useAdBlockerConflict';

export const ErrorLayout: FC = () => {
  const {
    errorMessage: defaultErrorMessage,
    isSubscriptionInfoError: defaultIsSubscriptionInfoError,
    isBrowserError: defaultIsBrowserError,
    showProxyConflict: defaultShowProxyConflict,
    showAdBlockerConflict: defaultShowAdBlockerConflict,
    requiredVersion,
  } = useLoaderData() as {
    errorMessage: LocalStorageData['errorMessage'];
    isSubscriptionInfoError: LocalStorageData['isSubscriptionInfoError'];
    isBrowserError: LocalStorageData['isBrowserError'];
    showProxyConflict: boolean;
    showAdBlockerConflict: boolean;
    requiredVersion: MetaApiData['requiredVersion'];
  };

  const { errorMessage, handleRetry } = useErrorScreen(defaultErrorMessage);
  const { showProxyConflict, handleProxyConflictClick } = useProxyConflict(
    defaultShowProxyConflict,
  );
  const { showAdBlockerConflict, handleAdBlockerConflictClick } =
    useAdBlockerConflict(defaultShowAdBlockerConflict);
  const isOutdatedVersion = useIsOutdatedVersion(requiredVersion);

  const { featuresList } = useFeaturesList();

  const [isSubscriptionInfoError] = useLocalStorage(
    [LocalStorageKey.IsSubscriptionInfoError],
    defaultIsSubscriptionInfoError,
  );
  const [isBrowserError, setIsBrowserError] = useLocalStorage(
    [LocalStorageKey.IsBrowserError],
    defaultIsBrowserError,
  );

  if (isOutdatedVersion) {
    return <OldVersionError />;
  }

  if (isSubscriptionInfoError) {
    return <Error code={1002} />;
  }

  if (errorMessage) {
    return <Error text={errorMessage} onClose={handleRetry} />;
  }

  if (isBrowserError) {
    return (
      <BrowserError
        onClick={async () => {
          await setIsBrowserError(undefined);
        }}
      />
    );
  }

  if (
    showProxyConflict &&
    featuresList[Feature.ProxyControlledByOtherExtensionsVisibility]
  ) {
    return (
      <ProxyControlledByOtherExtensions
        onClick={handleProxyConflictClick}
        conflictType="proxy"
      />
    );
  }

  if (
    showAdBlockerConflict &&
    featuresList[Feature.ProxyControlledByOtherExtensionsVisibility]
  ) {
    return (
      <ProxyControlledByOtherExtensions
        onClick={handleAdBlockerConflictClick}
        conflictType="adBlocker"
      />
    );
  }

  return <Outlet />;
};
