import { versionStringToNumber } from '@ulta-plus/extension-feature-toggle';
import { browser_api } from '@app/browser_api';

export function useIsOutdatedVersion(requiredVersion: string): boolean {
  const currentVersion = browser_api.runtime.getManifest().version;
  return (
    versionStringToNumber(currentVersion) <
    versionStringToNumber(requiredVersion)
  );
}
