import i18n from 'i18next';
import { isSupportedLanguage, resources, supportedLngs } from './languages';
import { initI18n } from '@app/i18n';
import { logger } from '@utils/logger';

await initI18n({
  context: 'popup',
  enableReact: true,
  debug: false,
  onLanguageChanged: async (language) => {
    logger.info('Popup language changed to:', language);
  },
});

export { supportedLngs, resources, isSupportedLanguage };
export default i18n;
