import { getMetaApiData } from '@utils/metaApiData';
import { featureStore } from '@ulta-plus/extension-feature-toggle';
import { Feature } from '@app/features/types/Feature';
import i18n from '@popup/shared/utils/i18n';
import { getLocalStorageData } from '@app/storage/local/shared';
import { LocalStorageKey } from '@app/storage/local/types/sharedTypes';

export const supportPageLoader = async () => {
  const [
    { supportUrl: configSupportUrl },
    { featuresList },
    { hasPremium, userId },
  ] = await Promise.all([
    getMetaApiData(),
    featureStore.getSnapshotAsync(),
    getLocalStorageData([LocalStorageKey.HasPremium, LocalStorageKey.UserId]),
  ]);

  const isSupportViaTg = featuresList[Feature.IsSupportViaTg];
  const SUPPORT_URL_VIA_TG = process.env.SUPPORT_URL;
  const supportUrl = isSupportViaTg ? SUPPORT_URL_VIA_TG : configSupportUrl;

  if (!supportUrl) {
    throw new Response(i18n.t('youboost:support-page.error.no-support-url'), {
      status: 404,
    });
  }

  return {
    supportUrl,
    isSupportViaTg,
    hasPremium: Boolean(hasPremium),
    userId,
  };
};
