import { FC } from 'react';
import {
  type Props as SecondaryWrapperProps,
  SecondaryWrapper,
} from '@popup/project/youboost/components/shared/SecondaryWrapper';
import {
  IconTextSection,
  type Props as IconTextSectionProps,
} from '@popup/project/youboost/components/IconTextSection';
import { Title } from '@popup/project/youboost/components/shared/Title';

interface Props {
  headerTitle: string;
  footer: SecondaryWrapperProps['footer'];
  closeClickHandler: NonNullable<SecondaryWrapperProps['closeClickHandler']>;
  icon: IconTextSectionProps['icon'];
  text: IconTextSectionProps['text'];
  bodyTitle: IconTextSectionProps['title'];
  children?: IconTextSectionProps['children'];
}

export const StatusLayout: FC<Props> = ({
  headerTitle,
  footer,
  closeClickHandler,
  icon,
  bodyTitle,
  text,
  children,
}) => {
  return (
    <SecondaryWrapper
      header={<Title title={headerTitle} />}
      footer={footer}
      closeClickHandler={closeClickHandler}
    >
      <IconTextSection icon={icon} title={bodyTitle} text={text}>
        {children}
      </IconTextSection>
    </SecondaryWrapper>
  );
};
