import { FC } from 'react';
import { useTranslation } from 'react-i18next';
import { browser_api } from '@app/browser_api';
import { LocalStorageKey } from '@app/storage/local/types/sharedTypes';
import { Button } from '@popup/project/youboost/components/shared/Button';

import s from './Footer.module.css';
import {
  getLocalStorageData,
  setLocalStorageData,
} from '@app/storage/local/shared';
import { RoutePath } from '@popup/project/youboost/routes/types/RoutePath';
import { useNavigate } from 'react-router-dom';
import { buildSupportUrl } from '@utils/buildSupportUrl';

interface Props {
  clearInitialEntry: () => Promise<void>;
  closeHandler: () => Promise<void>;
  supportUrl: string;
  showFreeContent: boolean;
}

const DIAGNOSTIC_URL = process.env.DIAGNOSTIC_EXTENSIONS_URL;

export const Footer: FC<Props> = ({
  supportUrl,
  closeHandler,
  showFreeContent,
  clearInitialEntry,
}) => {
  const navigate = useNavigate();
  const { t } = useTranslation('youboost', { keyPrefix: 'support-page' });

  const goToSupportHandler = async () => {
    const { deviceId, userId, email } = await getLocalStorageData([
      LocalStorageKey.UserId,
      LocalStorageKey.DeviceId,
      LocalStorageKey.email,
    ]);
    const url = buildSupportUrl({
      baseUrl: supportUrl,
      params: { ID: userId, deviceId, email },
    });
    await browser_api.tabs.create({ url });
  };

  const selfDiagnosisBotHandler = async () => {
    if (!DIAGNOSTIC_URL) {
      await setLocalStorageData({
        [LocalStorageKey.ErrorMessage]: t('error.no-diagnostic-url'),
      });
      return;
    }
    await browser_api.tabs.create({ url: DIAGNOSTIC_URL });
  };

  const buyPremiumHandler = async () => {
    navigate(RoutePath.Tariffs);
    await clearInitialEntry();
  };

  if (showFreeContent) {
    return (
      <div className={s.box} data-testid={'support-footer'}>
        <Button
          onClick={buyPremiumHandler}
          size={'default'}
          color={'primary'}
          data-testid={'button-buy-premium'}
        >
          {t('free.buttons.buy-premium')}
        </Button>
        <Button
          onClick={goToSupportHandler}
          size={'default'}
          color={'secondary'}
          data-testid={'button-payment-question'}
        >
          {t('free.buttons.payment-question')}
        </Button>
        <Button
          onClick={selfDiagnosisBotHandler}
          size={'default'}
          color={'tertiary'}
          data-testid={'button-self-diagnosis-bot'}
        >
          {t('free.buttons.self-diagnosis-bot')}
        </Button>
      </div>
    );
  }

  return (
    <div className={s.box} data-testid={'support-footer'}>
      <Button
        onClick={goToSupportHandler}
        size={'default'}
        color={'primary'}
        data-testid={'button-go-to-support'}
      >
        {t('premium.buttons.go-to-support')}
      </Button>
      <Button
        onClick={closeHandler}
        size={'default'}
        color={'tertiary'}
        data-testid={'button-close'}
      >
        {t('premium.buttons.close')}
      </Button>
    </div>
  );
};
