import { useTranslation } from 'react-i18next';
import { useNavigate } from 'react-router-dom';
import { Button } from '@popup/project/youboost/components/shared/Button';
import { RoutePath } from '@popup/project/youboost/routes/types/RoutePath';

import styles from './FooterButtons.module.css';

export const FooterButtons = ({
  onNext,
}: {
  onNext: () => void;
}): React.ReactNode => {
  const { t } = useTranslation('youboost', {
    keyPrefix: 'cancel-premium.problem.actions',
  });
  const navigate = useNavigate();

  const handleSupport = () => {
    navigate(RoutePath.Support);
  };

  return (
    <div className={styles.buttons}>
      <Button color="primary" size="default" onClick={handleSupport}>
        {t('contact')}
      </Button>
      <Button color="tertiary" size="default" onClick={onNext}>
        {t('continue')}
      </Button>
    </div>
  );
};
