import { LocalStorageData } from '@app/storage/local/types/sharedTypes';

type SupportParams = {
  ID?: string;
  userId?: LocalStorageData['userId'];
  deviceId?: LocalStorageData['deviceId'];
  email?: LocalStorageData['email'];
};

export const buildSupportUrl = ({
  baseUrl,
  params,
}: {
  baseUrl: string;
  params: SupportParams;
}) => {
  const url = new URL(baseUrl);

  Object.entries(params).forEach(([key, value]) => {
    if (value !== undefined) {
      url.searchParams.set(key, String(value));
    }
  });

  return url.toString();
};
