import { FC } from 'react';
import { SecondaryWrapper } from '@popup/project/youboost/components/shared/SecondaryWrapper';
import { Trans, useTranslation } from 'react-i18next';
import { Footer } from './Footer/Footer';
import { IconTextSection } from '@popup/project/youboost/components/IconTextSection';
import { SmileMessage } from '@popup/project/youboost/components/shared/icons';
import s from './SupportAlternative.module.css';
import { LocalStorageData } from '@app/storage/local/types/sharedTypes';

interface Props {
  clearInitialEntry: () => Promise<void>;
  closeHandler: () => Promise<void>;
  supportUrl: string;
  hasPremium: NonNullable<LocalStorageData['hasPremium']>;
  userId: LocalStorageData['userId'];
}

export const SupportAlternative: FC<Props> = ({
  clearInitialEntry,
  closeHandler,
  supportUrl,
  hasPremium,
  userId,
}) => {
  const { t } = useTranslation('youboost', { keyPrefix: 'support-page' });
  const showFreeContent = typeof userId !== 'undefined' && !hasPremium;

  return (
    <SecondaryWrapper
      header={t('header')}
      footer={
        <Footer
          clearInitialEntry={clearInitialEntry}
          closeHandler={closeHandler}
          supportUrl={supportUrl}
          showFreeContent={showFreeContent}
        />
      }
      closeClickHandler={closeHandler}
    >
      <div className={s.body} data-testid={'settings-body'}>
        <IconTextSection
          icon={<SmileMessage className={s.icon} />}
          title={t(showFreeContent ? 'free.title' : 'premium.title')}
          text={
            <span className={s.description}>
              <Trans
                t={t}
                i18nKey={showFreeContent ? 'free.text' : 'premium.text'}
                components={{
                  br: <br />,
                  b: <b />,
                }}
              />
            </span>
          }
        />
      </div>
    </SecondaryWrapper>
  );
};
