import { FC } from 'react';
import {
  isRouteErrorResponse,
  useNavigate,
  useRouteError,
} from 'react-router-dom';
import { Error as ErrorComponent } from '@popup/project/youboost/components/shared/errors/Error';
import { RoutePath } from '@popup/project/youboost/routes/types/RoutePath';

interface Props {}

export const GlobalError: FC<Props> = ({}) => {
  const error = useRouteError();
  const navigate = useNavigate();

  const closeHandler = () => {
    navigate(RoutePath.Root);
  };

  if (error instanceof Error) {
    return <ErrorComponent text={error.message} onClose={closeHandler} />;
  }

  if (isRouteErrorResponse(error)) {
    return (
      <ErrorComponent
        text={typeof error.data === 'string' ? error.data : undefined}
        code={error.status}
        onClose={closeHandler}
      />
    );
  }

  return <ErrorComponent onClose={closeHandler} />;
};
